import type { Colors } from 'components/Chart/Bar/Waterfall/types';
import { theme } from 'theme';

import type { PerformanceAndBreakdownMockForceFlags } from '../types';

/** Preset KPI slugs (lowercase) — constant names follow glossary abbreviations. */
export const PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG = {
  VOLUME: 'volume',
  NR: 'nr',
  MACO: 'maco',
  MACO_MARGIN: 'maco-margin',
} as const;

export {
  INNOVATION_HUB_PAGE_NAME,
  INNOVATION_HUB_PB_MOCK_ONLY as PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
} from '../../../constants';

export const PERFORMANCE_AND_BREAKDOWN_GLOBAL_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.globalTitle';

export const PERFORMANCE_AND_BREAKDOWN_SCOPED_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.scopedTitle';

export const PERFORMANCE_AND_BREAKDOWN_OVERTIME_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.Overtime.title';

export const PERFORMANCE_AND_BREAKDOWN_CONTRIBUTION_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.Contribution.title';

export const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.DeepDive.title';

export const PERFORMANCE_AND_BREAKDOWN_ERROR_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.errorTitle';

export const PERFORMANCE_AND_BREAKDOWN_ERROR_DESCRIPTION_I18N_ID =
  'Innovation.InnovationHub.PB.errorDescription';

export const PERFORMANCE_AND_BREAKDOWN_EMPTY_TITLE_I18N_ID =
  'Innovation.InnovationHub.PB.emptyTitle';

export const PERFORMANCE_AND_BREAKDOWN_EMPTY_DESCRIPTION_I18N_ID =
  'Innovation.InnovationHub.PB.emptyDescription';

export const PERFORMANCE_AND_BREAKDOWN_MEASURE_I18N_ID: Record<string, string> =
  {
    [PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG.VOLUME]:
      'Innovation.InnovationHub.PB.measure.volume',
    [PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG.NR]:
      'Innovation.InnovationHub.PB.measure.nr',
    [PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG.MACO]:
      'Innovation.InnovationHub.PB.measure.maco',
    [PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG.MACO_MARGIN]:
      'Innovation.InnovationHub.PB.measure.macoMargin',
  };

export const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PLUGIN_COLORS = {
  connectBars: theme.colors.txt.default,
  verticalGuidelines: theme.colors.charts.bg.diverging.Zero,
} as const;

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_API_KEY =
  'innovation-hub-waterfall-dimensions';

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_DIMENSIONS_STATE_KEY =
  'innovation_hub_waterfall_dimensions';

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_DATA_API_KEY =
  'innovation-hub-waterfall-options';

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY =
  'innovation_hub_waterfall_options';

export const PERFORMANCE_AND_BREAKDOWN_WATERFALL_COLORS: Colors = {
  first: '#C9D1D6',
  last: '#4C5965',
  negative: '#D62222',
  positive: '#009900',
};

export const PERFORMANCE_AND_BREAKDOWN_MOCK_FORCE_BY_SECTION: Record<
  'overtime' | 'contribution' | 'deepDive',
  PerformanceAndBreakdownMockForceFlags
> = {
  overtime: { skeleton: false, empty: false, error: false },
  contribution: { skeleton: false, empty: false, error: false },
  deepDive: { skeleton: false, empty: false, error: false },
};
